// A JNA Library to expose the extern-C FFI definitions.
// This is an implementation detail which will be called internally by the public API.

// For large crates we prevent `MethodTooLargeException` (see #2340)
// N.B. the name of the extension is very misleading, since it is
// rather `InterfaceTooLargeException`, caused by too many methods
// in the interface for large crates.
//
// By splitting the otherwise huge interface into two parts
// * UniffiLib (this)
// * IntegrityCheckingUniffiLib
// And all checksum methods are put into `IntegrityCheckingUniffiLib`
// we allow for ~2x as many methods in the UniffiLib interface.
//
// Note: above all written when we used JNA's `loadIndirect` etc.
// We now use JNA's "direct mapping" - unclear if same considerations apply exactly.
internal object IntegrityCheckingUniffiLib {
    init {
        Native.register(IntegrityCheckingUniffiLib::class.java, findLibraryName(componentName = "sync_core"))
        uniffiCheckContractApiVersion(this)
        uniffiCheckApiChecksums(this)
    }

    internal fun ensureInitialized() = Unit
    external fun uniffi_sync_core_checksum_method_httpsyncclient_cancel(
    ): Int
    external fun uniffi_sync_core_checksum_method_httpsyncclient_limits(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_load(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_save(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_clear(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_save_batch(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_load_batches(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncheckpointstore_clear_batch(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncredentialprovider_bearer(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigncredentialprovider_on_rotated(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigndownloadsink_write_verified(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreigndownloadsink_finish(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreignfilesource_len(
    ): Int
    external fun uniffi_sync_core_checksum_method_foreignfilesource_read_at(
    ): Int
