/**
 * Why `connect` gave no client. Messages are fixed strings: nothing from the server reaches `Display`.
 */
sealed class ConnectException(message: String): kotlin.Exception(message) {
        
    /**
     * `sync.server_url` is `http://` and the build does not have `allow-plain-http`.
     */
        class InsecureScheme(message: String) : ConnectException(message)
        
    /**
     * No usable answer from the server: no connection, a failed TLS 1.3 / `h2` handshake, a timeout, or a refusal to serve.
     */
        class Unreachable(message: String) : ConnectException(message)
        
    /**
     * `message` is meant for the user. `update_url` is `None` when the client decided itself: `server-info` carries none.
     */
        class UpgradeRequired(message: String) : ConnectException(message)
        
    /**
     * The server's `server-info` is outside what this client accepts; `what` names the field.
     */
        class ProtocolMismatch(message: String) : ConnectException(message)
        
        class Unauthorized(message: String) : ConnectException(message)
        
    /**
     * A local setting the client cannot use (a malformed server URL, client family or client version).
     */
        class InvalidConfig(message: String) : ConnectException(message)
        
    /**
     * Android only: the app has not initialised the system trust store in this process
     * (`TlsTrustBridge.nativeInit`), so no TLS connection is attempted.
     */
        class TrustStoreUninitialized(message: String) : ConnectException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ConnectException> {
        override fun lift(error_buf: RustBuffer.ByValue): ConnectException = FfiConverterTypeConnectError.lift(error_buf)
    }
}

