 * per-operation errors of `sync_api.md`. Wire codes become values of this type in
 * [`map_problem`](crate::map_problem), and `InvalidCode` in the mobile code exchange's own reading.
 */
sealed class SyncException(message: String): kotlin.Exception(message) {
        
        class Transport(message: String) : SyncException(message)
        
        class Cancelled(message: String) : SyncException(message)
        
    /**
     * `message` is the server text meant for the user; `update_url` is kept only when it is an `https` URL.
     */
