        class BlobUnavailable(message: String) : SyncException(message)
        
        class NotAFolder(message: String) : SyncException(message)
        
        class NameConflict(message: String) : SyncException(message)
        
        class InvalidName(message: String) : SyncException(message)
        
        class Cycle(message: String) : SyncException(message)
        
        class ParentNotFound(message: String) : SyncException(message)
        
        class ParentGone(message: String) : SyncException(message)
        
    /**
