        class QuotaExceeded(message: String) : SyncException(message)
        
        class SizeTooLarge(message: String) : SyncException(message)
        
        class SessionCapReached(message: String) : SyncException(message)
        
        class FreeSpaceFloor(message: String) : SyncException(message)
        
        class StagedCapReached(message: String) : SyncException(message)
        
        class BatchTooLarge(message: String) : SyncException(message)
        
        class CommitIdReused(message: String) : SyncException(message)
        
        class BlocklistMismatch(message: String) : SyncException(message)
        
