                Unit
            }
            is SyncException.NameConflict -> {
                buf.putInt(12)
                Unit
            }
            is SyncException.InvalidName -> {
                buf.putInt(13)
                Unit
            }
            is SyncException.Cycle -> {
                buf.putInt(14)
                Unit
            }
            is SyncException.ParentNotFound -> {
                buf.putInt(15)
                Unit
            }
            is SyncException.ParentGone -> {
                buf.putInt(16)
                Unit
            }
            is SyncException.EditedSince -> {
                buf.putInt(17)
                Unit
            }
            is SyncException.QuotaExceeded -> {
                buf.putInt(18)
                Unit
            }
            is SyncException.SizeTooLarge -> {
                buf.putInt(19)
                Unit
            }
            is SyncException.SessionCapReached -> {
                buf.putInt(20)
                Unit
            }
            is SyncException.FreeSpaceFloor -> {
                buf.putInt(21)
                Unit
            }
            is SyncException.StagedCapReached -> {
                buf.putInt(22)
                Unit
            }
            is SyncException.BatchTooLarge -> {
                buf.putInt(23)
                Unit
            }
            is SyncException.CommitIdReused -> {
                buf.putInt(24)
                Unit
            }
            is SyncException.BlocklistMismatch -> {
                buf.putInt(25)
                Unit
            }
            is SyncException.ResyncRequired -> {
                buf.putInt(26)
                Unit
            }
            is SyncException.SourceChanged -> {
                buf.putInt(27)
                Unit
            }
            is SyncException.Io -> {
                buf.putInt(28)
                Unit
            }
            is SyncException.HashMismatch -> {
                buf.putInt(29)
                Unit
            }
            is SyncException.ProtocolViolation -> {
                buf.putInt(30)
                Unit
            }
            is SyncException.InvalidCode -> {
                buf.putInt(31)
                Unit
            }
            is SyncException.DeviceGrantRefused -> {
                buf.putInt(32)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Where a large upload stands.
 */

enum class UploadState {
    
    /**
     * `block_hashes` holds the blocks hashed so far; `file_hash` and `session_id` are not known yet.
     */
    HASHING,
    /**
     * The file is hashed and the session is open.
     */
    UPLOADING,
    /**
     * Every needed block is acknowledged and the commit was sent.
     */
    COMMITTING;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeUploadState: FfiConverterRustBuffer<UploadState> {
    override fun read(buf: ByteBuffer) = try {
        UploadState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: UploadState) = 4UL

    override fun write(value: UploadState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalDuration: FfiConverterRustBuffer<java.time.Duration?> {
    override fun read(buf: ByteBuffer): java.time.Duration? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterDuration.read(buf)
    }

    override fun allocationSize(value: java.time.Duration?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterDuration.allocationSize(value)
        }
    }

    override fun write(value: java.time.Duration?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterDuration.write(value, buf)
        }
    }
}




